WITH patches AS (SELECT '{"a3_freeze":{"duration_turns":40,"permanent":false,"term_control":{"min_turns":4,"max_turns":40,"default_turns":8,"step_turns":4,"cancellable":true,"happiness":{"reference_turns":20,"short_factor":0.6,"long_factor":1.4},"note":"Vigencia elegible de 1 a 10 años. Preferencias sociales residuales, positivas y negativas, se multiplican por 0,6 a 1,4 (1 a 5 años: interpolación hasta 1; 5 a 10 años: hasta 1,4). Hipótesis editable, no estimación causal. La escasez y el esfuerzo de acceso se calculan aparte con anuncios y precios; no se multiplican dos veces."},"explanation":"Mantiene la renta nominal de los contratos cubiertos en el importe que tenían al aprobar la medida. No rebaja esa renta ni congela el precio de venta. La barra decide qué proporción de contratos queda cubierta; 25 % significa uno de cada cuatro contratos del ámbito simulado, no una rebaja del 25 %. El segundo control financia registro, comprobación de subidas, reclamaciones y sanciones. Vigencia elegible: 1–10 años. Los importes legales son nominales; los precios del tablero y la comparación se muestran en euros constantes de 2026. La media incluye contratos no cubiertos y puede evolucionar aunque un contrato esté congelado. Con IPC del 2 %, una renta nominal congelada pierde aproximadamente un 18 % de valor real en diez años.","audit_note":"Aprobar el límite no implica pagar la diferencia al propietario. El gasto del juego es exclusivamente su ejecución: registro e intercambio de datos, tramitación de denuncias, inspección, auditoría y expedientes sancionadores. A vigilancia cero no se asigna gasto adicional; se supone un cumplimiento espontáneo del 10 %. Con todos los medios alcanza el 95 %. Son supuestos editables, no tasas de fraude observadas. Una vigencia mayor mantiene durante más tiempo tanto la protección como la retirada de oferta y la dificultad de acceso. La retirada es un supuesto específico de cada medida, proporcional a su alcance, cumplimiento y dureza efectiva. No implica que todos los inquilinos se beneficien ni que toda la oferta desaparezca.","sources":["bde_2025","sf_rent","berlin","lau","ecb_inflation_target"]},"a3_index_cap":{"duration_turns":40,"permanent":false,"term_control":{"min_turns":4,"max_turns":40,"default_turns":20,"step_turns":4,"cancellable":true,"happiness":{"reference_turns":20,"short_factor":0.6,"long_factor":1.4},"note":"Vigencia elegible de 1 a 10 años. Preferencias sociales residuales, positivas y negativas, se multiplican por 0,6 a 1,4 (1 a 5 años: interpolación hasta 1; 5 a 10 años: hasta 1,4). Hipótesis editable, no estimación causal. La escasez y el esfuerzo de acceso se calculan aparte con anuncios y precios; no se multiplican dos veces."},"explanation":"Limita la subida anual de contratos vigentes. No fija la renta inicial de un contrato nuevo. El control muestra directamente la subida anual máxima permitida: 0 % equivale a congelar y 4 % permite hasta un 4 % anual. Es un límite de escenario, no el IRAV oficial futuro. El alcance nacional supuesto se puede editar en el panel interno. Vigencia elegible: 1–10 años. Los importes legales son nominales; los precios del tablero y la comparación se muestran en euros constantes de 2026. La media incluye contratos no cubiertos y puede evolucionar aunque un contrato esté congelado. La actualización real es (1 + subida nominal)/(1 + IPC) − 1: baja si el límite es inferior al IPC, permanece si coincide y puede subir si lo supera. El límite legal aplicable depende del contrato y la normativa; no se identifica automáticamente con el IPC.","audit_note":"Aprobar el límite no implica pagar la diferencia al propietario. El gasto del juego es exclusivamente su ejecución: registro e intercambio de datos, tramitación de denuncias, inspección, auditoría y expedientes sancionadores. A vigilancia cero no se asigna gasto adicional; se supone un cumplimiento espontáneo del 10 %. Con todos los medios alcanza el 95 %. Son supuestos editables, no tasas de fraude observadas. Una vigencia mayor mantiene durante más tiempo tanto la protección como la retirada de oferta y la dificultad de acceso. La retirada es un supuesto específico de cada medida, proporcional a su alcance, cumplimiento y dureza efectiva. No implica que todos los inquilinos se beneficien ni que toda la oferta desaparezca.","sources":["bde_2025","eu_rent","lau","ecb_inflation_target","ine_irav_methodology"]},"a3_benchmark":{"duration_turns":40,"permanent":false,"term_control":{"min_turns":4,"max_turns":40,"default_turns":20,"step_turns":4,"cancellable":true,"happiness":{"reference_turns":20,"short_factor":0.6,"long_factor":1.4},"note":"Vigencia elegible de 1 a 10 años. Preferencias sociales residuales, positivas y negativas, se multiplican por 0,6 a 1,4 (1 a 5 años: interpolación hasta 1; 5 a 10 años: hasta 1,4). Hipótesis editable, no estimación causal. La escasez y el esfuerzo de acceso se calculan aparte con anuncios y precios; no se multiplican dos veces."},"explanation":"Fija una renta máxima por características y zona utilizando una base de contratos comparables. La rebaja elegida aproxima cuánto queda el tope por debajo del alquiler actual de referencia, no un porcentaje de municipios ni de inspectores. Se aplica a la cuota de contratos indicada en el modelo. Es una propuesta genérica; las modalidades nacionales del catálogo tienen reglas y excepciones propias. Vigencia elegible: 1–10 años. Los importes legales son nominales; los precios del tablero y la comparación se muestran en euros constantes de 2026. La media incluye contratos no cubiertos y puede evolucionar aunque un contrato esté congelado.","audit_note":"Aprobar el límite no implica pagar la diferencia al propietario. El gasto del juego es exclusivamente su ejecución: registro e intercambio de datos, tramitación de denuncias, inspección, auditoría y expedientes sancionadores. A vigilancia cero no se asigna gasto adicional; se supone un cumplimiento espontáneo del 10 %. Con todos los medios alcanza el 95 %. Son supuestos editables, no tasas de fraude observadas. Una vigencia mayor mantiene durante más tiempo tanto la protección como la retirada de oferta y la dificultad de acceso. La retirada es un supuesto específico de cada medida, proporcional a su alcance, cumplimiento y dureza efectiva. No implica que todos los inquilinos se beneficien ni que toda la oferta desaparezca.","sources":["bde_2025","law_housing","bde_rent","ecb_inflation_target"]},"a3_income_cap":{"duration_turns":40,"permanent":false,"term_control":{"min_turns":4,"max_turns":40,"default_turns":20,"step_turns":4,"cancellable":true,"happiness":{"reference_turns":20,"short_factor":0.6,"long_factor":1.4},"note":"Vigencia elegible de 1 a 10 años. Preferencias sociales residuales, positivas y negativas, se multiplican por 0,6 a 1,4 (1 a 5 años: interpolación hasta 1; 5 a 10 años: hasta 1,4). Hipótesis editable, no estimación causal. La escasez y el esfuerzo de acceso se calculan aparte con anuncios y precios; no se multiplican dos veces."},"explanation":"Limita el esfuerzo del hogar arrendatario en función de sus ingresos. El juego traduce ese límite a una rebaja equivalente del alquiler de referencia; no dispone de una distribución individual de ingresos y contratos para aplicar un porcentaje de esfuerzo a cada hogar. La comprobación de ingresos y contratos requiere medios. Es una propuesta hipotética, no una norma española vigente. Vigencia elegible: 1–10 años. Los importes legales son nominales; los precios del tablero y la comparación se muestran en euros constantes de 2026. La media incluye contratos no cubiertos y puede evolucionar aunque un contrato esté congelado.","audit_note":"Aprobar el límite no implica pagar la diferencia al propietario. El gasto del juego es exclusivamente su ejecución: registro e intercambio de datos, tramitación de denuncias, inspección, auditoría y expedientes sancionadores. A vigilancia cero no se asigna gasto adicional; se supone un cumplimiento espontáneo del 10 %. Con todos los medios alcanza el 95 %. Son supuestos editables, no tasas de fraude observadas. Una vigencia mayor mantiene durante más tiempo tanto la protección como la retirada de oferta y la dificultad de acceso. La retirada es un supuesto específico de cada medida, proporcional a su alcance, cumplimiento y dureza efectiva. No implica que todos los inquilinos se beneficien ni que toda la oferta desaparezca.","sources":["bde_2025","oecd_reform","eu_rent","ecb_inflation_target"]},"a3_cost_return":{"duration_turns":40,"permanent":false,"term_control":{"min_turns":4,"max_turns":40,"default_turns":20,"step_turns":4,"cancellable":true,"happiness":{"reference_turns":20,"short_factor":0.6,"long_factor":1.4},"note":"Vigencia elegible de 1 a 10 años. Preferencias sociales residuales, positivas y negativas, se multiplican por 0,6 a 1,4 (1 a 5 años: interpolación hasta 1; 5 a 10 años: hasta 1,4). Hipótesis editable, no estimación causal. La escasez y el esfuerzo de acceso se calculan aparte con anuncios y precios; no se multiplican dos veces."},"explanation":"Comparte la misma fórmula con la calculadora de alquiler por amortización de esta web: suma de amortizaciones anuales × (1 + rentabilidad / 100) / 12. La vivienda descuenta un 15 % residual y actualiza su base por IPC; reformas y equipamiento se amortizan a coste original. La rentabilidad del 8 % se aplica a la amortización anual, no al precio de mercado. La barra aproxima progresivamente el precio actual al calculado. Se usa una vivienda ilustrativa de 80 m², no una distribución nacional de activos. Los efectos sobre oferta, economía y felicidad son hipótesis del juego: la calculadora original no estima esos efectos. Vigencia elegible: 1–10 años. Los importes legales son nominales; los precios del tablero y la comparación se muestran en euros constantes de 2026. La media incluye contratos no cubiertos y puede evolucionar aunque un contrato esté congelado.","audit_note":"Aprobar el límite no implica pagar la diferencia al propietario. El gasto del juego es exclusivamente su ejecución: registro e intercambio de datos, tramitación de denuncias, inspección, auditoría y expedientes sancionadores. A vigilancia cero no se asigna gasto adicional; se supone un cumplimiento espontáneo del 10 %. Con todos los medios alcanza el 95 %. Son supuestos editables, no tasas de fraude observadas. Una vigencia mayor mantiene durante más tiempo tanto la protección como la retirada de oferta y la dificultad de acceso. La retirada es un supuesto específico de cada medida, proporcional a su alcance, cumplimiento y dureza efectiva. No implica que todos los inquilinos se beneficien ni que toda la oferta desaparezca.","sources":["bde_2025","oecd_actions","ecb_inflation_target"]},"a3_spain_rent":{"duration_turns":40,"permanent":false,"term_control":{"min_turns":4,"max_turns":40,"default_turns":20,"step_turns":4,"cancellable":true,"happiness":{"reference_turns":20,"short_factor":0.6,"long_factor":1.4},"note":"Vigencia elegible de 1 a 10 años. Preferencias sociales residuales, positivas y negativas, se multiplican por 0,6 a 1,4 (1 a 5 años: interpolación hasta 1; 5 a 10 años: hasta 1,4). Hipótesis editable, no estimación causal. La escasez y el esfuerzo de acceso se calculan aparte con anuncios y precios; no se multiplican dos veces."},"explanation":"Vincula la renta inicial a la del contrato anterior dentro de una zona declarada tensionada, con excepciones legales. Para grandes tenedores puede añadir un índice estatal de referencia y, en ciertos supuestos, alcanzar viviendas sin alquiler previo reciente. Se aplicó en España con la Ley de Vivienda de 2023, pero no funciona como un descuento uniforme en todo el país. La barra del juego simula una rebaja equivalente sobre el parque afectado, no un porcentaje literal de la ley. Vigencia elegible: 1–10 años. Los importes legales son nominales; los precios del tablero y la comparación se muestran en euros constantes de 2026. La media incluye contratos no cubiertos y puede evolucionar aunque un contrato esté congelado.","audit_note":"Aprobar el límite no implica pagar la diferencia al propietario. El gasto del juego es exclusivamente su ejecución: registro e intercambio de datos, tramitación de denuncias, inspección, auditoría y expedientes sancionadores. A vigilancia cero no se asigna gasto adicional; se supone un cumplimiento espontáneo del 10 %. Con todos los medios alcanza el 95 %. Son supuestos editables, no tasas de fraude observadas. Una vigencia mayor mantiene durante más tiempo tanto la protección como la retirada de oferta y la dificultad de acceso. La retirada es un supuesto específico de cada medida, proporcional a su alcance, cumplimiento y dureza efectiva. No implica que todos los inquilinos se beneficien ni que toda la oferta desaparezca.","sources":["law_housing","lau","ecb_inflation_target"]},"a3_germany_rent":{"duration_turns":40,"permanent":false,"term_control":{"min_turns":4,"max_turns":40,"default_turns":20,"step_turns":4,"cancellable":true,"happiness":{"reference_turns":20,"short_factor":0.6,"long_factor":1.4},"note":"Vigencia elegible de 1 a 10 años. Preferencias sociales residuales, positivas y negativas, se multiplican por 0,6 a 1,4 (1 a 5 años: interpolación hasta 1; 5 a 10 años: hasta 1,4). Hipótesis editable, no estimación causal. La escasez y el esfuerzo de acceso se calculan aparte con anuncios y precios; no se multiplican dos veces."},"explanation":"Limita la renta inicial de un nuevo contrato a partir de una renta comparable local. Puede excluir viviendas nuevas y la primera cesión tras una modernización integral, por lo que no congela todos los contratos. Este mecanismo se aplicó en Alemania mediante la Mietpreisbremse, con un máximo habitual de la referencia local más un 10 %. La barra representa una rebaja equivalente respecto a la referencia del juego. Vigencia elegible: 1–10 años. Los importes legales son nominales; los precios del tablero y la comparación se muestran en euros constantes de 2026. La media incluye contratos no cubiertos y puede evolucionar aunque un contrato esté congelado.","audit_note":"Aprobar el límite no implica pagar la diferencia al propietario. El gasto del juego es exclusivamente su ejecución: registro e intercambio de datos, tramitación de denuncias, inspección, auditoría y expedientes sancionadores. A vigilancia cero no se asigna gasto adicional; se supone un cumplimiento espontáneo del 10 %. Con todos los medios alcanza el 95 %. Son supuestos editables, no tasas de fraude observadas. Una vigencia mayor mantiene durante más tiempo tanto la protección como la retirada de oferta y la dificultad de acceso. La retirada es un supuesto específico de cada medida, proporcional a su alcance, cumplimiento y dureza efectiva. No implica que todos los inquilinos se beneficien ni que toda la oferta desaparezca.","sources":["rent_de","rent_de_exceptions","ecb_inflation_target"]},"a3_france_rent":{"duration_turns":40,"permanent":false,"term_control":{"min_turns":4,"max_turns":40,"default_turns":20,"step_turns":4,"cancellable":true,"happiness":{"reference_turns":20,"short_factor":0.6,"long_factor":1.4},"note":"Vigencia elegible de 1 a 10 años. Preferencias sociales residuales, positivas y negativas, se multiplican por 0,6 a 1,4 (1 a 5 años: interpolación hasta 1; 5 a 10 años: hasta 1,4). Hipótesis editable, no estimación causal. La escasez y el esfuerzo de acceso se calculan aparte con anuncios y precios; no se multiplican dos veces."},"explanation":"Establece una renta de referencia por zona y características del inmueble, junto con un máximo por encima de esa referencia. Puede admitir un complemento bajo condiciones concretas y permitir su impugnación. Este mecanismo se aplicó en varias ciudades francesas, donde el límite mayorado es del 20 %, y se distingue de limitar las subidas entre contratos. La barra aplica una rebaja equivalente al escenario, no modifica literalmente el porcentaje francés. Vigencia elegible: 1–10 años. Los importes legales son nominales; los precios del tablero y la comparación se muestran en euros constantes de 2026. La media incluye contratos no cubiertos y puede evolucionar aunque un contrato esté congelado.","audit_note":"Aprobar el límite no implica pagar la diferencia al propietario. El gasto del juego es exclusivamente su ejecución: registro e intercambio de datos, tramitación de denuncias, inspección, auditoría y expedientes sancionadores. A vigilancia cero no se asigna gasto adicional; se supone un cumplimiento espontáneo del 10 %. Con todos los medios alcanza el 95 %. Son supuestos editables, no tasas de fraude observadas. Una vigencia mayor mantiene durante más tiempo tanto la protección como la retirada de oferta y la dificultad de acceso. La retirada es un supuesto específico de cada medida, proporcional a su alcance, cumplimiento y dureza efectiva. No implica que todos los inquilinos se beneficien ni que toda la oferta desaparezca.","sources":["rent_fr","ecb_inflation_target"]},"a3_netherlands_rent":{"duration_turns":40,"permanent":false,"term_control":{"min_turns":4,"max_turns":40,"default_turns":20,"step_turns":4,"cancellable":true,"happiness":{"reference_turns":20,"short_factor":0.6,"long_factor":1.4},"note":"Vigencia elegible de 1 a 10 años. Preferencias sociales residuales, positivas y negativas, se multiplican por 0,6 a 1,4 (1 a 5 años: interpolación hasta 1; 5 a 10 años: hasta 1,4). Hipótesis editable, no estimación causal. La escasez y el esfuerzo de acceso se calculan aparte con anuncios y precios; no se multiplican dos veces."},"explanation":"Calcula una renta máxima a partir de puntos por superficie, equipamiento, eficiencia y otras características de la vivienda. Puede abarcar alquiler social y segmento medio, mientras que el tramo libre queda fuera del tope según los puntos del inmueble. Se aplicó en Países Bajos, donde la regulación de 2024 alcanzó contratos de hasta 186 puntos. La barra aproxima una rebaja equivalente porque el simulador no dispone de fichas individuales para puntuar cada casa. Vigencia elegible: 1–10 años. Los importes legales son nominales; los precios del tablero y la comparación se muestran en euros constantes de 2026. La media incluye contratos no cubiertos y puede evolucionar aunque un contrato esté congelado.","audit_note":"Aprobar el límite no implica pagar la diferencia al propietario. El gasto del juego es exclusivamente su ejecución: registro e intercambio de datos, tramitación de denuncias, inspección, auditoría y expedientes sancionadores. A vigilancia cero no se asigna gasto adicional; se supone un cumplimiento espontáneo del 10 %. Con todos los medios alcanza el 95 %. Son supuestos editables, no tasas de fraude observadas. Una vigencia mayor mantiene durante más tiempo tanto la protección como la retirada de oferta y la dificultad de acceso. La retirada es un supuesto específico de cada medida, proporcional a su alcance, cumplimiento y dureza efectiva. No implica que todos los inquilinos se beneficien ni que toda la oferta desaparezca.","sources":["rent_nl","ecb_inflation_target"]},"a3_sweden_rent":{"duration_turns":40,"permanent":false,"term_control":{"min_turns":4,"max_turns":40,"default_turns":20,"step_turns":4,"cancellable":true,"happiness":{"reference_turns":20,"short_factor":0.6,"long_factor":1.4},"note":"Vigencia elegible de 1 a 10 años. Preferencias sociales residuales, positivas y negativas, se multiplican por 0,6 a 1,4 (1 a 5 años: interpolación hasta 1; 5 a 10 años: hasta 1,4). Hipótesis editable, no estimación causal. La escasez y el esfuerzo de acceso se calculan aparte con anuncios y precios; no se multiplican dos veces."},"explanation":"Compara viviendas equivalentes para determinar una renta razonable, dando prioridad a los alquileres negociados entre propietarios y asociaciones locales de inquilinos. No fija un techo nacional uniforme: importan las características de la vivienda y los comparables de la zona. Este modelo se aplicó en Suecia mediante la negociación y el valor de uso. La barra simula el resultado de una negociación más restrictiva; no es una regla porcentual sueca. Vigencia elegible: 1–10 años. Los importes legales son nominales; los precios del tablero y la comparación se muestran en euros constantes de 2026. La media incluye contratos no cubiertos y puede evolucionar aunque un contrato esté congelado.","audit_note":"Aprobar el límite no implica pagar la diferencia al propietario. El gasto del juego es exclusivamente su ejecución: registro e intercambio de datos, tramitación de denuncias, inspección, auditoría y expedientes sancionadores. A vigilancia cero no se asigna gasto adicional; se supone un cumplimiento espontáneo del 10 %. Con todos los medios alcanza el 95 %. Son supuestos editables, no tasas de fraude observadas. Una vigencia mayor mantiene durante más tiempo tanto la protección como la retirada de oferta y la dificultad de acceso. La retirada es un supuesto específico de cada medida, proporcional a su alcance, cumplimiento y dureza efectiva. No implica que todos los inquilinos se beneficien ni que toda la oferta desaparezca.","sources":["rent_se","ecb_inflation_target"]},"a3_berlin_rent":{"duration_turns":40,"permanent":false,"term_control":{"min_turns":4,"max_turns":40,"default_turns":20,"step_turns":4,"cancellable":true,"happiness":{"reference_turns":20,"short_factor":0.6,"long_factor":1.4},"note":"Vigencia elegible de 1 a 10 años. Preferencias sociales residuales, positivas y negativas, se multiplican por 0,6 a 1,4 (1 a 5 años: interpolación hasta 1; 5 a 10 años: hasta 1,4). Hipótesis editable, no estimación causal. La escasez y el esfuerzo de acceso se calculan aparte con anuncios y precios; no se multiplican dos veces."},"explanation":"Combina una congelación de rentas con tablas de máximos y reducción de alquileres que superen esos límites. Es un tope fuerte que puede cambiar rápidamente las rentas cubiertas, pero exige una competencia legal clara y un sistema intenso de control. Se aplicó de forma temporal en Berlín como Mietendeckel y el Tribunal Constitucional alemán lo anuló en 2021 por una cuestión competencial. Aquí es un precedente histórico e hipotético, no una norma vigente ni trasladable sin reforma competencial. Vigencia elegible: 1–10 años. Los importes legales son nominales; los precios del tablero y la comparación se muestran en euros constantes de 2026. La media incluye contratos no cubiertos y puede evolucionar aunque un contrato esté congelado.","audit_note":"Aprobar el límite no implica pagar la diferencia al propietario. El gasto del juego es exclusivamente su ejecución: registro e intercambio de datos, tramitación de denuncias, inspección, auditoría y expedientes sancionadores. A vigilancia cero no se asigna gasto adicional; se supone un cumplimiento espontáneo del 10 %. Con todos los medios alcanza el 95 %. Son supuestos editables, no tasas de fraude observadas. Una vigencia mayor mantiene durante más tiempo tanto la protección como la retirada de oferta y la dificultad de acceso. La retirada es un supuesto específico de cada medida, proporcional a su alcance, cumplimiento y dureza efectiva. No implica que todos los inquilinos se beneficien ni que toda la oferta desaparezca.","sources":["rent_berlin","ecb_inflation_target"]},"a3_voluntary_cap":{"duration_turns":40,"permanent":false,"term_control":{"min_turns":4,"max_turns":40,"default_turns":20,"step_turns":4,"cancellable":true,"happiness":{"reference_turns":20,"short_factor":0.6,"long_factor":1.4},"note":"Vigencia elegible de 1 a 10 años. Preferencias sociales residuales, positivas y negativas, se multiplican por 0,6 a 1,4 (1 a 5 años: interpolación hasta 1; 5 a 10 años: hasta 1,4). Hipótesis editable, no estimación causal. La escasez y el esfuerzo de acceso se calculan aparte con anuncios y precios; no se multiplican dos veces."},"explanation":"Los propietarios se adhieren voluntariamente a un alquiler más bajo a cambio de un beneficio de IRPF ligado al convenio. El 25 % significa 12.500 de las 50.000 viviendas previstas, no un 25 % de descuento. El modelo imputa 250 €/mes de menor recaudación por vivienda: es un incentivo ilustrativo, no el cálculo legal de una deducción. El beneficio se mantiene durante el convenio y no puede financiarse subiendo IRPF, tampoco desde otra medida mientras coincidan sus vigencias. Convenio elegible de 1 a 10 años; una mayor vigencia prolonga sus beneficios y costes sociales. Los precios del tablero se expresan en euros de 2026.","audit_note":"Gestión inicial: 100 € por vivienda adherida. Beneficio fiscal supuesto: 250 €/mes por vivienda (750 €/trimestre). Se registra como menor recaudación de IRPF; no como transferencia y beneficio fiscal a la vez. Los porcentajes legales de reducción del rendimiento neto del alquiler dependen de los requisitos de la Ley de Vivienda y no equivalen a 250 € fijos.","sources":["plan2026","law_housing"]},"a3_protected_sale":{"duration_turns":40,"permanent":false,"term_control":{"min_turns":4,"max_turns":40,"default_turns":40,"step_turns":4,"cancellable":true,"happiness":{"reference_turns":20,"short_factor":0.6,"long_factor":1.4},"note":"Vigencia elegible de 1 a 10 años. Preferencias sociales residuales, positivas y negativas, se multiplican por 0,6 a 1,4 (1 a 5 años: interpolación hasta 1; 5 a 10 años: hasta 1,4). Hipótesis editable, no estimación causal. La escasez y el esfuerzo de acceso se calculan aparte con anuncios y precios; no se multiplican dos veces."},"explanation":"Establece el máximo de venta y reventa de viviendas calificadas como protegidas durante su periodo de protección. Se verifica precio por m² útil, requisitos del comprador y transmisiones para evitar sobreprecios ocultos. No fija un precio máximo a toda la vivienda libre. La barra muestra la rebaja del máximo respecto al precio de referencia del juego; el peso del parque afectado es una hipótesis del 5 %, editable. Cada comunidad tiene módulos y reglas propios: la cifra nacional de la simulación no los sustituye. Vigencia elegible: 1–10 años. Los importes legales son nominales; los precios del tablero y la comparación se muestran en euros constantes de 2026. La media incluye contratos no cubiertos y puede evolucionar aunque un contrato esté congelado.","audit_note":"Aprobar el límite no implica pagar la diferencia al propietario. El gasto del juego es exclusivamente su ejecución: registro e intercambio de datos, tramitación de denuncias, inspección, auditoría y expedientes sancionadores. A vigilancia cero no se asigna gasto adicional; se supone un cumplimiento espontáneo del 10 %. Con todos los medios alcanza el 95 %. Son supuestos editables, no tasas de fraude observadas. Una vigencia mayor mantiene durante más tiempo tanto la protección como la retirada de oferta y la dificultad de acceso. La retirada es un supuesto específico de cada medida, proporcional a su alcance, cumplimiento y dureza efectiva. No implica que todos los inquilinos se beneficien ni que toda la oferta desaparezca.","sources":["bde_2025","law_housing","plan2026","ecb_inflation_target"]},"a3_sale_resale_cap":{"duration_turns":40,"permanent":false,"term_control":{"min_turns":4,"max_turns":40,"default_turns":40,"step_turns":4,"cancellable":true,"happiness":{"reference_turns":20,"short_factor":0.6,"long_factor":1.4},"note":"Vigencia elegible de 1 a 10 años. Preferencias sociales residuales, positivas y negativas, se multiplican por 0,6 a 1,4 (1 a 5 años: interpolación hasta 1; 5 a 10 años: hasta 1,4). Hipótesis editable, no estimación causal. La escasez y el esfuerzo de acceso se calculan aparte con anuncios y precios; no se multiplican dos veces."},"explanation":"Limita el precio de reventa de viviendas que entran en un régimen asequible, tomando un precio inicial y una actualización anual limitada. La dureza fija el descuento inicial y el precio máximo evoluciona después con el índice del programa. Se inspira en la reventa controlada de Ginebra y en las cláusulas del bail réel solidaire francés, aplicadas a parques concretos. Requiere registro y vigilancia; no es un tope ya vigente para todas las viviendas españolas. Vigencia elegible: 1–10 años. Los importes legales son nominales; los precios del tablero y la comparación se muestran en euros constantes de 2026. La media incluye contratos no cubiertos y puede evolucionar aunque un contrato esté congelado.","audit_note":"Coste de la ley no confundido con su ejecución: hipótesis de 1.000 puestos equivalentes a 70.000 €/año, más 10.000 €/puesto de implantación, registros y sistemas. Dureza y vigilancia independientes. Cobertura nacional, cumplimiento y retirada de anuncios son supuestos, no estimaciones de los precedentes extranjeros. Descuento inicial 0–30 %, actualización 2 % anual: hipótesis del juego, no traslación de un índice legal extranjero.  Una vigencia mayor mantiene durante más tiempo tanto la protección como la retirada de oferta y la dificultad de acceso. La retirada es un supuesto específico de cada medida, proporcional a su alcance, cumplimiento y dureza efectiva. No implica que todos los inquilinos se beneficien ni que toda la oferta desaparezca.","sources":["existing_geneva","existing_brs","ecb_inflation_target"]},"a3_sale_cost_cap":{"duration_turns":40,"permanent":false,"term_control":{"min_turns":4,"max_turns":40,"default_turns":40,"step_turns":4,"cancellable":true,"happiness":{"reference_turns":20,"short_factor":0.6,"long_factor":1.4},"note":"Vigencia elegible de 1 a 10 años. Preferencias sociales residuales, positivas y negativas, se multiplican por 0,6 a 1,4 (1 a 5 años: interpolación hasta 1; 5 a 10 años: hasta 1,4). Hipótesis editable, no estimación causal. La escasez y el esfuerzo de acceso se calculan aparte con anuncios y precios; no se multiplican dos veces."},"explanation":"Establece un precio máximo a partir del coste auditado de la promoción o rehabilitación más un margen permitido. La barra ajusta ese margen y otra barra financia la comprobación de costes y ventas. Se inspira en el control de precios y márgenes de las zonas de desarrollo de Ginebra; aquí se plantea extenderlo a un parque delimitado. Los costes declarados pueden inflarse y la vigilancia insuficiente reduce la efectividad. Vigencia elegible: 1–10 años. Los importes legales son nominales; los precios del tablero y la comparación se muestran en euros constantes de 2026. La media incluye contratos no cubiertos y puede evolucionar aunque un contrato esté congelado.","audit_note":"Coste de la ley no confundido con su ejecución: hipótesis de 1.000 puestos equivalentes a 70.000 €/año, más 10.000 €/puesto de implantación, registros y sistemas. Dureza y vigilancia independientes. Cobertura nacional, cumplimiento y retirada de anuncios son supuestos, no estimaciones de los precedentes extranjeros. Coste de referencia 1.900 €/m² y crecimiento 2 %: plantilla hipotética de coste auditable; no media oficial de compra. Margen seleccionable 0–30 %.  Una vigencia mayor mantiene durante más tiempo tanto la protección como la retirada de oferta y la dificultad de acceso. La retirada es un supuesto específico de cada medida, proporcional a su alcance, cumplimiento y dureza efectiva. No implica que todos los inquilinos se beneficien ni que toda la oferta desaparezca.","sources":["existing_geneva_cost","ecb_inflation_target"]},"a3_sale_general_cap":{"duration_turns":40,"permanent":false,"term_control":{"min_turns":4,"max_turns":40,"default_turns":40,"step_turns":4,"cancellable":true,"happiness":{"reference_turns":20,"short_factor":0.6,"long_factor":1.4},"note":"Vigencia elegible de 1 a 10 años. Preferencias sociales residuales, positivas y negativas, se multiplican por 0,6 a 1,4 (1 a 5 años: interpolación hasta 1; 5 a 10 años: hasta 1,4). Hipótesis editable, no estimación causal. La escasez y el esfuerzo de acceso se calculan aparte con anuncios y precios; no se multiplican dos veces."},"explanation":"Fija un máximo de venta respecto al precio de referencia y permite elegir su rebaja. La vigilancia se financia por separado para comprobar operaciones e impedir pagos ocultos. Es una extensión hipotética al mercado libre de mecanismos que en los precedentes consultados se aplican a vivienda controlada o protegida. Baja los precios regulados, pero puede retirar anuncios y dificultar la venta o inversión. Vigencia elegible: 1–10 años. Los importes legales son nominales; los precios del tablero y la comparación se muestran en euros constantes de 2026. La media incluye contratos no cubiertos y puede evolucionar aunque un contrato esté congelado.","audit_note":"Coste de la ley no confundido con su ejecución: hipótesis de 1.000 puestos equivalentes a 70.000 €/año, más 10.000 €/puesto de implantación, registros y sistemas. Dureza y vigilancia independientes. Cobertura nacional, cumplimiento y retirada de anuncios son supuestos, no estimaciones de los precedentes extranjeros. Descuento 0–50 % sobre referencia: propuesta hipotética, sin precedente general español.  Una vigencia mayor mantiene durante más tiempo tanto la protección como la retirada de oferta y la dificultad de acceso. La retirada es un supuesto específico de cada medida, proporcional a su alcance, cumplimiento y dureza efectiva. No implica que todos los inquilinos se beneficien ni que toda la oferta desaparezca.","sources":["existing_geneva","existing_brs","ecb_inflation_target"]}}'::jsonb AS data), changed AS (
 SELECT base.*, jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{metadata}','{"id":"vivienda-realism","notes":"Añadida regularización de viviendas consolidadas con oferta formal, aptitud registral y financiación potencial separadas. Acceso y protección: costes por beneficiario, referencias ejecutadas, avales contingentes, parque público y suspensión cancelable. Regularización: máximo conservador 100.000 expedientes; 95 % ya utilizado, solo 5 % de disponibilidad adicional; efectos colectivos reducidos. Fiscalidad: selectores de tipo/recargo, dos componentes ITP/AJD, IRPF/IS, nuevas bases explícitas, recaudación propia y bloqueo transversal del mismo impuesto. Expropiación para alquiler público: justiprecio aproximado, 5 % legal separado, tramitación y rechazo político explícitos. Aplicadas todas las recomendaciones de coherencia: mercado segmentado, stock público, producción privada, beneficiarios, contabilidad financiera, esfuerzo de compra y fiscalidad por hogar. Felicidad social: todos los colectivos salvo no residentes, incidencia fiscal reforzada, PIB real y rebote colectivo finito. Alquiler inicial corregido a la media aritmética AEAT 2024: 9,00 €/m²/mes, territorio fiscal común; mediana SERPAVI sustituida. Sustituida acogida temporal por cupo para nuevas autorizaciones de teletrabajo internacional de rentas altas; controles, costes y canales económicos propios.","title":"Modelo nacional de vivienda","version":"0.12.0-alpha.collective1.mean1.remote1.controls1","created_at":"2026-10-04T00:00:00.000Z","updated_at":"2026-10-05T11:58:00.648Z"}'::jsonb),'{model,version}','"0.12.0-alpha.collective1.mean1.remote1.controls1"'::jsonb),'{model,scenario,consumer_inflation}','{"annual_rate":0.02,"base_year":2026,"note":"Supuesto de IPC del 2 % anual para expresar precios en euros constantes de 2026; editable, no previsión oficial para España. El objetivo del BCE sirve de referencia de largo plazo, no es el deflactor del PIB ni una obligación de actualizar cada contrato por IPC."}'::jsonb),'{model,sources}',payload->'model'->'sources'||'[{"id":"ecb_inflation_target","title":"BCE · objetivo de inflación del 2 % a medio plazo","url":"https://www.ecb.europa.eu/mopo/strategy/pricestab/html/index.en.html","note":"Objetivo del conjunto del área del euro; referencia de escenario, no previsión del IPC español.","accessed":"2026-10-05"},{"id":"ine_irav_methodology","title":"INE · metodología del IRAV","url":"https://www.ine.es/daco/daco42/irav/meto_IRAV.pdf","note":"El índice de actualización de contratos se distingue del IPC y del crecimiento del alquiler de mercado.","accessed":"2026-10-05"}]'::jsonb),'{model,release_history}','{"label":"Alfa 0.12","current":"0.12.0-alpha","releases":[{"date":"2026-10-03","label":"Alfa 0.12","changes":["Escenario nacional con demografía dinámica, referencias oficiales y fuentes consultables.","Impuestos y presupuestos ajustables en ambos sentidos, persistentes y con comprobación de financiación.","Informes trimestrales con curvas superpuestas del último año y balance final de partida.","Banco de 120 plantillas de comentarios adaptativos.","Integración en la web, navegación móvil y pie de página común."],"version":"0.12.0-alpha"}],"history_note":"El registro de versiones comienza en Alfa 0.12. Las iteraciones anteriores no disponen de un historial numerado validado.","entries":[{"version":"0.12.0-alpha.collective1.mean1.remote1.controls1","date":"2026-10-05","title":"Revisión común de controles de precios","changes":["Vigencia 1–10 años, efectos sociales de ambos signos y costes hasta vencimiento.","Precios visibles en euros constantes de 2026, IPC separado y editable.","Retirada de oferta ligada a la restricción efectiva; revisión de comentarios generales."]},{"version":"0.12.0-alpha.collective1.mean1.remote1","date":"2026-10-05","changes":["Sustituida acogida temporal por cupo y umbral de rentas altas para nuevos teletrabajadores internacionales; flujos, demanda, consumo, costes y efectos colectivos propios."]},{"version":"0.12.0-alpha.migration2","date":"2026-10-04","summary":"Migración: presupuesto, expulsiones, retorno con bonus separado, límites acumulados y efectos persistentes; retirada de integración laboral y mediación."},{"version":"0.12.0-alpha.help1","date":"2026-10-04","summary":"Ayudas breves con cifras, reparto de competencias por medida y fuentes oficiales; catálogo cerrado al iniciar."},{"version":"0.12.0-alpha.coherence1","date":"2026-10-04","summary":"Revisión completa de coherencia: esfuerzo de compra, oferta anunciada y mercados segmentados; parque público persistente, capacidad constructiva, inversión privada, reservas de seguros, beneficiarios y perfiles fiscales por hogar. Controles sin efectos heredados, rehabilitación condicionada y programas territoriales sin población ficticia."},{"version":"0.12.0-alpha.collective1","date":"2026-10-05","summary":"Felicidad colectiva ponderada de todos los colectivos nacionales; recortes y presión fiscal con efectos sociales fuertes, PIB real y rebote por sensibilidad de grupo. Indicador en diseño de cada medida."}]}'::jsonb) AS updated
 FROM public.sim_model_versions base WHERE id='0.12.0-alpha.collective1.mean1.remote1' AND source_sha256='039c403e36dab02d531a4b4ee50815e26451718477ec34f4c7da1bc19ead7639'
)
INSERT INTO public.sim_model_versions(id,label,status,engine_id,payload,engine_manifest,source_sha256)
SELECT '0.12.0-alpha.collective1.mean1.remote1.controls1',label,'published',engine_id,jsonb_set(updated,'{model,measures}',(SELECT jsonb_agg(CASE WHEN patches.data ? (item->>'id') THEN jsonb_set(item||(patches.data->(item->>'id')),'{effects}',(SELECT jsonb_agg(CASE WHEN (effect->>'permanent')::boolean THEN effect ELSE jsonb_set(effect,'{duration_turns}','40'::jsonb) END ORDER BY eo) FROM jsonb_array_elements(item->'effects') WITH ORDINALITY es(effect,eo))) ELSE item END ORDER BY ord) FROM jsonb_array_elements(updated->'model'->'measures') WITH ORDINALITY arr(item,ord))),'{"assets/simulator/housing-policy.js":"5dc84e21a1c3f4dcb44d29075ece481c4a6f96e943b8ea8f93d4f65cb97901b4","assets/simulator/model-config.js":"80a29812c03d0965d19b3bb0abceb302837b3c2d1a47fdd0c72c6b67921b4cc0","assets/simulator/advanced.js":"b1132d34f047675c1a8fd67f17c68c65d2a789086498a8a9ccea5a981fb11219","assets/simulator/national.js":"099037f5602d5dd1e82821ec02c210883713dccdac8664eb7aef6d585b7d81f9","assets/simulator/fiscal.js":"3e7f8c8cf217b6577d5d9582079467047e3723cb61a087d01d8132de01dcd940","assets/simulator/turn-report.js":"3c10a46fe83730aad54e320882a2746a4e803a68cdb6d8ac764c1c7cb06e6a5b"}'::jsonb,'edc5748eebc2f6d2eaff6798c17ddba473a2e122616becd238d740fa988e1f7c' FROM changed CROSS JOIN patches;
